create table orberadar_private.review_events (id uuid primary key default gen_random_uuid(),candidate_id uuid not null references orberadar_private.candidates(id),deadline timestamptz not null,evidence text not null check(length(trim(evidence))>=15),created_at timestamptz not null default now()); alter table orberadar_private.review_events enable row level security; revoke all on orberadar_private.review_events from public,anon,authenticated;